	'messages:apihelp-translationstats-param-group' => 'en:List of groups to fetch statistics for. See <kbd>[[Special:ApiHelp/query+messagegroups|action=query&meta=messagegroups]]</kbd>.',
	'messages:apihelp-translationstats-param-language' => 'en:List of languages to fetch statistics for.',
	'messages:apihelp-translationstats-param-scale' => 'en:Scale of the translation statistics',
	'messages:apihelp-translationstats-param-start' => 'en:Starting date from which to fetch translation statistics. Defaults to current date minus the number of <var>days</var>.',
	'messages:apihelp-translationstats-example-1' => 'en:Fetch edit count for the last 30 days, for all groups and languages',
	'messages:apihelp-translationstats-example-2' => 'en:Fetch edit count for the last 30 days, for languages English and French.',
	'messages:apihelp-markfortranslation-summary' => 'en:Mark a page for translation',
	'messages:apihelp-markfortranslation-param-title' => 'en:The title of the page to act on. Either <var>title</var> or <var>pageid</var> must be set.',
	'messages:apihelp-markfortranslation-param-pageid' => 'en:The page ID of the page to act on. Either <var>title</var> or <var>pageid</var> must be set.',
	'messages:apihelp-markfortranslation-param-revid' => 'en:Assert that the current version of the page has this revision ID before continuing. If the page has been updated, exit with an error.',
	'messages:apihelp-markfortranslation-param-translatetitle' => 'en:If <kbd>yes</kbd>, allow translation of the display title. If <kbd>no</kbd>, do not allow translation. If absent, allow translation unless the page previously disallowed translation, or if the page is a template.',
	'messages:apihelp-markfortranslation-param-prioritylanguages' => 'en:A list of priority language codes. If this is absent, any previously set value will be retained.',
	'messages:apihelp-markfortranslation-param-forcepriority' => 'en:This parameter is ignored unless the <var>prioritylanguages</var> parameter is present. If <kbd>true</kbd>, prevent translations to languages other than the priority languages.',
	'messages:apihelp-markfortranslation-param-priorityreason' => 'en:This parameter is ignored unless the <var>prioritylanguages</var> parameter is present. A string giving the reason for priority translation.',
	'messages:apihelp-markfortranslation-param-nofuzzyunits' => 'en:A list of translation unit IDs which should not be fuzzied. This will be merged with the default list, in which any units with only tvar changes will not be fuzzied.',
	'messages:apihelp-markfortranslation-param-fuzzyunits' => 'en:A list of translation unit IDs which should be fuzzied. This is only useful to override the default and allows fuzzying even units with only tvar changes.',
	'messages:apihelp-markfortranslation-param-forcelatestsyntaxversion' => 'en:If <kbd>false</kbd>, do not use latest syntax version for this page. If absent, latest syntax version is used.',
	'messages:apihelp-markfortranslation-param-transclusion' => 'en:If <kbd>yes</kbd> or absent, enable translation aware transclusion for this page. If <kbd>no</kbd>, disable transclusion.',
	'messages:apierror-translate-changeset-modified' => 'en:The changeset has been modified by another user or process. Your changes cannot be saved as it might override their changes. Please refresh the page to see the latest changes.',
	'messages:apierror-translate-fuzzymessage' => 'en:Cannot review fuzzy translations',
	'messages:apierror-translate-groupreviewdisabled' => 'en:Message group review not in use.',
	'messages:apierror-translate-invalidaggregategroupname' => 'en:Invalid aggregate message group name',
