	'messages:apierror-translate-invalidlanguage' => 'en:Language code $1 is not valid.',
	'messages:apierror-translate-notranslationservices' => 'en:No public translation services have been configured. The wiki administrator needs to set <var>$wgTranslateTranslationServices</var> appropriately before this feature can be used.',
